// The default rule prices every product type without a row of its own. Only added if it's missing.
if ($input.all().some(i => i.json.product_type === 'default')) return [];
return [{ json: {
  product_type: 'default',
  margin_floor_pct: 0,         // 0 = break-even: the floor covers cost, card fees and shipping you absorb
  cost_plus_multiplier: 1.6,   // cost x 1.6 (plus tax where prices include it) when there's no RRP
  fee_pct: 2,                  // your payment provider's card fee, in %
  fee_fixed: 0.30,             // and its fixed fee per order
  undercut_amount: 0.01,       // how far under the cheapest trusted competitor
  cost_change_pct: 5,          // flag a cost move this big since the price was last set
  notes: 'Every product type without its own row',
} }];

