// One decision per variant: a target from a competitor, RRP or cost plus, never under break-even, with the reason in words.
const s = $('Pricing settings').first().json;
const call = $('Reprice these variants').isExecuted ? $('Reprice these variants').first().json : {};
const only = call.variant_ids ? new Set(call.variant_ids) : null;
const approved = new Set(call.approve || []);
const t = s.prices_include_tax ? s.tax_rate : 0;          // tax inside your shelf prices
const day = 864e5, now = Date.now();
const cents = n => Math.round(n * 100) / 100;
const up = n => Math.ceil(n * 100 - 1e-6) / 100;           // round up to the cent
const ending = n => {                                     // round up to the price ending, such as .95
  if (s.price_ending == null) return up(n);
  const w = Math.floor(n);
  return cents(w + s.price_ending >= n - 1e-9 ? w + s.price_ending : w + 1 + s.price_ending);
};
const money = n => new Intl.NumberFormat(s.locale, { style: 'currency', currency: s.currency }).format(n);

// Pricing rules by product type, with default for everything else.
const rules = {};
for (const { json: r } of $('Get pricing rules').all()) if (r.product_type) rules[r.product_type.trim().toLowerCase()] = r;
if (!rules.default) throw new Error('pricing_rules has no default row. Run the Setup lane.');
const ruleFor = type => rules[(type || '').trim().toLowerCase()] || rules.default;

// Competitor prices, on the same tax footing as yours.
const theirs = l => {
  let p = Number(l.last_price);
  if (s.market_shows_tax && (s.tax_exclusive_domains || []).includes(l.domain)) p *= 1 + s.tax_rate;
  if (s.market_shows_tax !== s.prices_include_tax) p = s.market_shows_tax ? p / (1 + s.tax_rate) : p * (1 + s.tax_rate);
  return cents(p);
};
const excluded = (s.exclude_competitors || []).map(x => x.toLowerCase());
const listings = {};
if (s.use_competitor_prices)
  for (const { json: l } of $('Get competitor listings').all())
    if (l.product_key && Number(l.last_price) > 0) (listings[l.product_key] ||= []).push(l);
function cheapest(list = []) {
  let stale = 0;
  const trusted = list.filter(l => {
    if (!['ok', 'robots_disallowed'].includes(l.status) || l.in_stock === false || Number(l.confidence) < s.min_confidence) return false;
    if ([l.domain, l.seller].some(v => v && excluded.includes(v.toLowerCase()))) return false;
    if (now - new Date(l.last_checked_at).getTime() > s.max_price_age_days * day) { stale++; return false; }
    return true;
  }).map(l => ({ ...l, price: theirs(l) }));
  // A price far under the median is usually a different pack size, a typo or a misread page.
  let kept = trusted;
  if (trusted.length >= 3) {
    const ps = trusted.map(l => l.price).sort((a, b) => a - b), m = ps.length >> 1;
    const median = ps.length % 2 ? ps[m] : (ps[m - 1] + ps[m]) / 2;
    kept = trusted.filter(l => l.price >= median * s.outlier_below_median);
  }
  kept.sort((a, b) => a.price - b.price);
  return { best: kept[0] || null, stale: stale > 0 && !kept.length };
}

// What's left after tax, card fees and any shipping you absorb.
const shipping = price => s.free_shipping_over != null && price >= s.free_shipping_over ? s.shipping_you_absorb || 0 : 0;
const net = (price, r) => price / (1 + t) - price * r.fee_pct / 100 - r.fee_fixed - shipping(price);
// The lowest price that still covers cost plus the margin floor, after tax, fees and shipping.
const floorFor = (cost, r, ship) => up((cost * (1 + r.margin_floor_pct / 100) + ship + r.fee_fixed) / (1 / (1 + t) - r.fee_pct / 100));

const stored = {};
for (const { json: d } of $('Get decisions').all()) if (d.variant_id) stored[d.variant_id] = d;

const pages = $('Read variants').all().map(i => i.json);
const bad = pages.find(p => p.errors || !p.data?.productVariants);
if (bad) throw new Error('Shopify did not return the variants: ' + JSON.stringify(bad.errors || bad).slice(0, 300));
const variants = pages.flatMap(p => p.data.productVariants.nodes).filter(v => !only || only.has(v.id));

let noCost = 0, staleListings = 0;
const decisions = variants.map(v => {
  const prev = stored[v.id] || {};
  const r = ruleFor(v.product.productType);
  const cost = Number(v.inventoryItem?.unitCost?.amount) || 0;
  const current = Number(v.price);
  const rrp = Number(v.compareAtPrice) > 0 ? Number(v.compareAtPrice) : null;
  const base = {
    variant_id: v.id, product_id: v.product.id, sku: v.sku || '', title: v.displayName.replace(/ - Default Title$/, ''),
    product_type: v.product.productType || '', product_status: v.product.status, current_price: current,
    cost: cost || null, last_cost: prev.last_cost ?? (cost || null), rrp, locked: prev.locked === true,
    calculated_at: new Date().toISOString(),
  };
  if (!cost) {
    noCost++;
    return { ...base, rule: 'no_cost', status: 'skipped', flags: '', explanation: 'No cost: not priced. Fill in Cost per item in Shopify.',
      competitor_price: null, competitor_name: null, competitor_url: null, competitor_checked_at: null,
      floor_price: null, target: null, proposed_price: null, move_pct: null, profit: null, kind: null, push_price: null };
  }

  // 1. The target: 1 cent under the cheapest trusted competitor, else RRP, else cost plus. Never above RRP.
  const { best, stale } = cheapest(listings[v.id]);
  if (stale) staleListings++;
  const costPlus = ending(cost * r.cost_plus_multiplier * (1 + t));
  const ceiling = rrp ?? costPlus;
  let target, rule, why;
  if (best && best.price - r.undercut_amount < ceiling) {
    target = cents(best.price - r.undercut_amount); rule = 'undercut';
    why = `Cheapest trusted competitor ${money(best.price)} at ${best.seller || best.domain}, so ${money(target)}.`;
  } else if (rrp) {
    target = rrp; rule = 'at_rrp';
    why = best ? `Cheapest trusted competitor ${money(best.price)} is at or above RRP, so RRP ${money(rrp)}.`
               : `No trusted competitor price, so RRP ${money(rrp)} (compare-at).`;
  } else {
    target = costPlus; rule = 'cost_plus';
    why = `No RRP and no cheaper trusted competitor, so cost ${money(cost)} x ${r.cost_plus_multiplier}${t ? ' plus tax' : ''}, rounded up: ${money(costPlus)}.`;
  }

  // 2. The floor. Shipping you absorb counts only when the price clears your free-shipping threshold.
  const f0 = floorFor(cost, r, 0), f1 = floorFor(cost, r, s.shipping_you_absorb || 0);
  const clears = p => s.free_shipping_over != null && p >= s.free_shipping_over;
  const floor = clears(Math.max(target, f0)) ? f1 : f0;
  let proposed = target;
  if (target < floor) { proposed = floor; rule = 'at_floor'; why += ` That's under the floor, so the floor: ${money(floor)}.`; }
  const profit = cents(net(proposed, r) - cost);
  const covers = ['cost', 'card fees', ...(shipping(proposed) ? ['the shipping you absorb'] : []), ...(r.margin_floor_pct ? [`a ${r.margin_floor_pct}% margin`] : [])];
  why += ` Floor ${money(floor)} covers ${covers.slice(0, -1).join(', ')} and ${covers.at(-1)}. Profit ${money(profit)} after fees.`;

  // 3. Flags: what a person might want to see.
  const move = current > 0 ? cents((proposed - current) / current * 100) : null;
  const flags = [];
  if (best && best.price < floor) flags.push('floor_breach');
  if (floor > ceiling) { flags.push('above_ceiling'); why += rrp ? ' Break-even is above RRP.' : ' Break-even is above the cost-plus price.'; }
  if (prev.last_cost > 0 && Math.abs(cost - prev.last_cost) / prev.last_cost * 100 >= r.cost_change_pct) flags.push('cost_change');
  if (move !== null && Math.abs(move) >= s.large_move_pct) flags.push('large_move');

  // 4. Status. A live price under break-even is fixed this run whatever its status: that's the floor fix.
  const floorNow = clears(current) ? f1 : f0;
  const fixPrice = clears(f0) ? f1 : f0;
  let status;
  if (base.locked) status = 'locked';
  else if (Math.abs(proposed - current) < 0.005) status = 'unchanged';
  else if (prev.status === 'kept' && Number(prev.held_price) === proposed) status = 'kept';
  else if (!approved.has(v.id) && (flags.some(f => (s.hold_on_flags || []).includes(f))
           || (prev.status === 'held' && Number(prev.proposed_price) === proposed))) {
    status = 'held';   // held until someone decides or the proposal changes, with the flags it was held for
    for (const f of String(prev.flags || '').split(',')) if (f && !flags.includes(f) && (s.hold_on_flags || []).includes(f)) flags.push(f);
  }
  else status = 'pending';
  const floorFix = current < floorNow - 0.004;
  const kind = floorFix ? 'floor_fix' : status === 'pending' ? 'change' : null;
  const push_price = status === 'pending' ? proposed : floorFix ? fixPrice : null;
  if (floorFix && push_price !== proposed) why += ` The live price ${money(current)} is under break-even, so it goes to ${money(push_price)} now.`;

  return { ...base, rule, status, flags: flags.join(','), explanation: why,
    competitor_price: best ? best.price : null, competitor_name: best ? best.seller || best.domain : null,
    competitor_url: best ? best.url : null, competitor_checked_at: best ? best.last_checked_at : null,
    floor_price: floor, target, proposed_price: proposed, move_pct: move, profit, kind, push_price };
});

return [{ json: { decisions, summary: {
  scope: only ? 'variants' : 'all', approved: [...approved], by: call.by || null,
  variants: variants.length, no_cost: noCost, stale_listings: staleListings,
} } }];

// Save only the decisions that changed, so a big catalogue isn't rewritten every hour.
const KEYS = ['product_status', 'current_price', 'cost', 'rrp', 'competitor_price', 'floor_price', 'proposed_price', 'rule', 'flags', 'status', 'locked'];
const stored = {};
for (const { json: d } of $('Get decisions').all()) if (d.variant_id) stored[d.variant_id] = d;
const same = (a, b) => (a ?? null) === (b ?? null) || (a != null && b != null && Number(a) === Number(b));
return $json.decisions
  .filter(d => !stored[d.variant_id] || KEYS.some(k => k === 'locked'
    ? Boolean(d.locked) !== Boolean(stored[d.variant_id].locked) : !same(d[k], stored[d.variant_id][k])))
  .map(d => ({ json: d }));

// Floor fixes first, then the biggest live moves up to the cap, then drafts. Stop live changes when the data looks wrong.
const s = $('Pricing settings').first().json;
const { decisions, summary } = $('Decide prices').first().json;
const last = $('Get last run').first().json || {};
const fixes = decisions.filter(d => d.kind === 'floor_fix');
const changes = decisions.filter(d => d.kind === 'change');
const live = changes.filter(d => d.product_status === 'ACTIVE')
  .sort((a, b) => Math.abs(b.move_pct ?? 0) - Math.abs(a.move_pct ?? 0));
const drafts = changes.filter(d => d.product_status !== 'ACTIVE');

// The bad-feed stop: when a feed or a scan goes wrong, it goes wrong everywhere, so hold every live change.
const reasons = [];
if (summary.scope === 'all') {
  const big = live.filter(d => d.flags.includes('large_move')).length;
  if (live.length >= s.stop_min_changes && big >= s.stop_min_large_moves && big / live.length * 100 > s.stop_large_move_share_pct)
    reasons.push(`${big} of ${live.length} live price changes move ${s.large_move_pct}% or more`);
  if (last.variants > 0 && summary.variants > 0
      && (summary.no_cost / summary.variants - last.no_cost / last.variants) * 100 > s.stop_missing_cost_jump_pct)
    reasons.push(`variants with no cost jumped from ${last.no_cost} to ${summary.no_cost}`);
}
const stopped = reasons.length > 0;
const sendLive = stopped ? [] : live.slice(0, s.per_run_cap);
const send = [...fixes, ...sendLive, ...drafts.slice(0, s.draft_lane_cap)];

const run = {
  run_id: String($execution.id), scope: summary.scope, started_at: $('Decide prices').first().json.decisions[0]?.calculated_at || new Date().toISOString(),
  variants: summary.variants, changes_due: fixes.length + changes.length, floor_fixes: fixes.length,
  held: decisions.filter(d => d.status === 'held').length, no_cost: summary.no_cost, stale_listings: summary.stale_listings,
  carried_over: live.length - sendLive.length, stopped, stop_reason: reasons.join('; ') || null, dry_run: s.dry_run,
};
// One Shopify call per product, carrying all its variants.
const byProduct = {};
for (const d of send) (byProduct[d.product_id] ||= []).push(d);
const items = Object.entries(byProduct).map(([product_id, rows]) => ({ json: {
  product_id, variants: rows.map(d => ({ id: d.variant_id, price: d.push_price.toFixed(2) })), rows, run } }));
return items.length ? items : [{ json: { product_id: null, rows: [], run } }];

