// Shopify answers HTTP 200 even when it refuses a change, so read the body. A failed row is tried again next run.
const s = $('Pricing settings').first().json;
const sent = $('Check the run').all().map(i => i.json);
const pushed = $('Push prices').isExecuted ? $('Push prices').all().map(i => i.json) : null;
const { approved, by } = $('Decide prices').first().json.summary;
const run = sent[0].run, now = new Date().toISOString();
const changes = [], updates = [], failed = [];
sent.forEach((b, i) => {
  if (!b.product_id || !pushed) return;           // nothing due, or dry run
  const r = pushed[i] || {}, res = r.data?.productVariantsBulkUpdate;
  const err = (r.errors || []).map(e => e.message).join('; ')
    || (res?.userErrors || []).map(e => e.message).join('; ')
    || (r.error ? String(r.error.message || r.error) : '')
    || (res ? '' : 'no answer from Shopify');
  for (const d of b.rows) {
    const source = d.kind === 'floor_fix' ? 'floor_fix' : approved.includes(d.variant_id) ? 'approved' : 'scheduled';
    if (err) { failed.push({ title: d.title, error: err }); updates.push({ variant_id: d.variant_id, status: 'failed', error: err, current_price: d.current_price, last_cost: d.last_cost, applied_at: null }); continue; }
    changes.push({ variant_id: d.variant_id, product_id: d.product_id, title: d.title, rule: source === 'floor_fix' ? 'floor_fix' : d.rule,
      source, run_id: run.run_id, changed_by: source === 'approved' ? by : 'repricer', from_price: d.current_price, to_price: d.push_price,
      move_pct: d.current_price > 0 ? Math.round((d.push_price - d.current_price) / d.current_price * 1000) / 10 : null,
      changed_at: now, reverted: false });
    updates.push({ variant_id: d.variant_id, status: d.push_price === d.proposed_price ? 'applied' : d.status, error: null,
      current_price: d.push_price, last_cost: d.cost, applied_at: now });
  }
});
run.changed = changes.length; run.failed = failed.length;
const big = changes.filter(c => c.source !== 'floor_fix' && Math.abs(c.move_pct ?? 0) >= s.large_move_pct);   // floor fixes are listed apart, with no Revert
const fixes = changes.filter(c => c.source === 'floor_fix');
return [{ json: { run, changes, updates, alert: run.stopped || fixes.length > 0 || big.length > 0 || failed.length > 0,
  fixes, big, failed } }];

// Run stopped, floor fixes, large moves (each with Revert) and failures, in one message.
const s = $('Pricing settings').first().json;
const { run, fixes, big, failed } = $('Read results').first().json;
const money = n => new Intl.NumberFormat(s.locale, { style: 'currency', currency: s.currency }).format(n);
const pct = n => (n > 0 ? '+' : '') + n + '%';
const blocks = [], lines = [];
if (run.stopped) lines.push(`:octagonal_sign: *Live price changes stopped:* ${run.stop_reason}. Floor fixes and drafts still went out. Check your cost data and the competitor scan, then run Decide again.`);
if (fixes.length) lines.push(`:arrow_up: *${fixes.length} price${fixes.length === 1 ? '' : 's'} lifted to break-even:*\n` + fixes.slice(0, 20).map(c => `• ${c.title}: ${money(c.from_price)} → ${money(c.to_price)}`).join('\n'));
if (failed.length) lines.push(`:warning: *${failed.length} change${failed.length === 1 ? '' : 's'} failed* (tried again next run): ` + [...new Set(failed.map(f => f.error))].slice(0, 3).join('; '));
for (const l of lines) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: l } });
if (big.length) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*${big.length} large move${big.length === 1 ? '' : 's'} applied:*` } });
  big.slice(0, 5).forEach((c, n) => blocks.push({ type: 'section', block_id: 'rev_' + n,
    text: { type: 'mrkdwn', text: `${c.title}\n${money(c.from_price)} → ${money(c.to_price)} (${pct(c.move_pct)})` },
    accessory: { type: 'button', action_id: 'price_revert', text: { type: 'plain_text', text: 'Revert' }, value: c.variant_id + '|' + c.run_id,
      confirm: { title: { type: 'plain_text', text: 'Put the old price back?' }, text: { type: 'mrkdwn', text: `Sets ${money(c.from_price)} and locks this variant.` },
        confirm: { type: 'plain_text', text: 'Revert' }, deny: { type: 'plain_text', text: 'Cancel' } } } }));
}
return [{ json: { channel: s.slack_alert_channel, text: run.stopped ? 'Repricing stopped: ' + run.stop_reason : 'Repricing: ' + run.changed + ' changes', blocks } }];

// One card per held price that hasn't had a card for this proposal yet.
const s = $('Review settings').first().json;
const money = n => n == null ? 'n/a' : new Intl.NumberFormat(s.locale, { style: 'currency', currency: s.currency }).format(n);
const pt = text => ({ type: 'plain_text', text });
const LABEL = { large_move: 'large move', floor_breach: 'a competitor is under your floor', cost_change: 'cost changed', above_ceiling: 'break-even is above RRP' };
return $input.all().map(i => i.json)
  .filter(d => d.variant_id && Number(d.card_price) !== Number(d.proposed_price))
  .slice(0, s.cards_per_run)
  .map(d => {
    const admin = `https://${s.store_domain}/admin/products/${d.product_id.split('/').pop()}/variants/${d.variant_id.split('/').pop()}`;
    const move = d.move_pct == null ? '' : ` (${d.move_pct > 0 ? '+' : ''}${d.move_pct}%)`;
    const blocks = [
      { type: 'header', text: pt('Price to check') },
      { type: 'section', text: { type: 'mrkdwn', text: `*<${admin}|${d.title}>*\n${d.explanation}` } },
      { type: 'section', fields: [
        { type: 'mrkdwn', text: `*Now*\n${money(d.current_price)}` },
        { type: 'mrkdwn', text: `*Proposed*\n${money(d.proposed_price)}${move}` },
        { type: 'mrkdwn', text: `*Floor*\n${money(d.floor_price)}` },
        { type: 'mrkdwn', text: `*Cheapest competitor*\n${d.competitor_price == null ? 'None trusted' : money(d.competitor_price) + ' at ' + d.competitor_name}` },
        { type: 'mrkdwn', text: `*Cost*\n${money(d.cost)}` },
        { type: 'mrkdwn', text: `*Profit after fees*\n${money(d.profit)}` },
      ] },
      { type: 'context', elements: [{ type: 'mrkdwn', text: 'Held because: ' + d.flags.split(',').filter(Boolean).map(f => LABEL[f] || f).join(', ') }] },
      { type: 'actions', block_id: 'price_actions', elements: [
        { type: 'button', action_id: 'price_apply', style: 'primary', text: pt('Apply ' + money(d.proposed_price)), value: d.variant_id + '|' + d.proposed_price },
        { type: 'button', action_id: 'price_hold', text: pt('Hold'), value: d.variant_id + '|' + d.proposed_price },
        { type: 'button', action_id: 'price_lock', style: 'danger', text: pt('Lock'), value: d.variant_id + '|' + d.proposed_price,
          confirm: { title: pt('Lock this price?'), text: { type: 'mrkdwn', text: 'The repricer stops changing this variant until you set `locked` back to false. Floor fixes still apply.' }, confirm: pt('Lock'), deny: pt('Cancel') } },
      ] },
    ];
    return { json: { variant_id: d.variant_id, proposed_price: d.proposed_price, old_channel: d.slack_channel, old_ts: d.slack_ts,
      text: `Price to check: ${d.title}`, blocks } };
  });

const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
if (Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) > 300) throw new Error('Stale request');
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || ''; // no URLSearchParams in the Code node
const p = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' ')));
const a = p.actions[0];
const [id, second] = a.value.split('|');
return [{ json: { base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'],
  action: a.action_id.replace('price_', ''), variant_id: id, price: Number(second), run_id: second, block_id: a.block_id,
  user: p.user.username || p.user.name || p.user.id, channel: p.channel.id, ts: p.message.ts, blocks: p.message.blocks || [] } }];

