// What happened, in one line for the message, or a reply in the thread when nothing changed.
const c = $('Parse click').first().json, s = $('Click settings').first().json;
const money = n => new Intl.NumberFormat(s.locale, { style: 'currency', currency: s.currency }).format(n);
const ran = n => $(n).isExecuted;
let ok = true, line = '', reply = '';
if (c.action === 'apply') {
  const d = $('Get the result').first().json;
  ok = d.status === 'applied';
  line = `:white_check_mark: Applied ${money(d.current_price)} by @${c.user}`;
  reply = s.dry_run ? 'Dry run: Shopify was not changed.' : `:warning: Not applied: ${d.error || 'the price is now ' + d.status + '. Check the Decide lane.'}`;
} else if (c.action === 'hold') {
  line = `:pause_button: Held at ${money($('Get the decision').first().json.current_price)} by @${c.user}. A new proposal gets a new card.`;
} else if (c.action === 'lock') {
  line = `:lock: Locked by @${c.user}. Set \`locked\` to false in price_decisions to unlock.`;
} else {
  const ch = $('Get the change').first().json;
  ok = ran('Log the revert');
  line = `:leftwards_arrow_with_hook: Reverted to ${money(ch.from_price)} and locked by @${c.user}`;
  reply = s.dry_run ? 'Dry run: Shopify was not changed.' : ':warning: Not reverted: ' + JSON.stringify(($('Put the old price back').first().json.data?.productVariantsBulkUpdate?.userErrors) || $('Put the old price back').first().json.errors || 'no answer from Shopify').slice(0, 300);
}
// A card loses its buttons; a digest or alert loses just the clicked line's button.
const note = { type: 'context', elements: [{ type: 'mrkdwn', text: line }] };
const blocks = c.action === 'revert'
  ? c.blocks.flatMap(b => b.block_id === c.block_id ? [{ ...b, accessory: undefined }, note] : [b])
  : [...c.blocks.filter(b => b.type !== 'actions'), note];
return [{ json: { ok, blocks: JSON.parse(JSON.stringify(blocks)), line, reply } }];

// The day in one message: what changed, what's waiting on you, and the biggest moves with Revert.
const s = $('Report settings').first().json;
const money = n => new Intl.NumberFormat(s.locale, { style: 'currency', currency: s.currency }).format(n);
const pct = n => (n > 0 ? '+' : '') + (Math.round(n * 10) / 10) + '%';
const rows = n => $(n).all().map(i => i.json);
const changes = rows('Get recent changes').filter(c => c.variant_id);
const runs = rows('Get recent runs').filter(r => r.run_id);
const decisions = rows('Get all decisions').filter(d => d.variant_id);
const moves = changes.filter(c => c.source !== 'revert');
const reverts = changes.length - moves.length;
const ups = moves.filter(c => c.to_price > c.from_price).length;
const withPct = moves.filter(c => c.move_pct != null);
const avg = withPct.length ? withPct.reduce((a, c) => a + c.move_pct, 0) / withPct.length : 0;
const fixes = moves.filter(c => c.source === 'floor_fix').length;
const stopped = runs.filter(r => r.stopped);
const failed = runs.reduce((a, r) => a + (r.failed || 0), 0);
const last = runs.filter(r => r.scope === 'all').sort((a, b) => String(b.started_at).localeCompare(String(a.started_at)))[0];
const count = f => decisions.filter(f).length;
const waiting = [
  [count(d => d.status === 'held'), 'held for a decision in Slack'],
  [count(d => (d.flags || '').includes('above_ceiling')), 'where break-even is above RRP: you lose money at list'],
  [count(d => d.rule === 'no_cost'), 'with no Cost per item, so not priced'],
  [last ? last.stale_listings : 0, 'whose competitor prices are all older than ' + s.max_price_age_days + ' days'],
].filter(([n]) => n > 0).map(([n, what]) => `• ${n} variant${n === 1 ? '' : 's'} ${what}`);
for (const r of stopped) waiting.unshift(`• :octagonal_sign: A run stopped: ${r.stop_reason}`);
const locked = count(d => d.locked === true);

const blocks = [{ type: 'header', text: { type: 'plain_text', text: 'Prices: the last 24 hours' } }];
if (!runs.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ':warning: The repricer hasn\'t run in 24 hours. Check the Decide lane\'s executions.' } });
else if (!moves.length && !waiting.length && !reverts)
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `:white_check_mark: All clear: no price changes. ${runs.length} run${runs.length === 1 ? '' : 's'}, none stopped.` } });
else {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text:
    `*${moves.length} price change${moves.length === 1 ? '' : 's'}*` + (moves.length ? ` (${ups} up, ${moves.length - ups} down, average ${pct(avg)})` : '')
    + `\n${fixes} floor fix${fixes === 1 ? '' : 'es'} · ${reverts} reverted · ${runs.length} run${runs.length === 1 ? '' : 's'}`
    + (failed ? ` · ${failed} failed` : '') + (locked ? ` · ${locked} locked` : '') } });
  if (waiting.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Waiting on you*\n' + waiting.join('\n') } });
}
if (last && last.dry_run) {
  const due = count(d => d.status === 'pending');
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `:test_tube: \`dry_run\` is on: ${due} change${due === 1 ? '' : 's'} waiting, nothing sent to Shopify.` }] });
}
// The biggest move per variant. Floor fixes show without Revert: going back would sell under break-even.
const seen = new Set();
const top = moves.filter(c => !c.reverted && c.move_pct != null).sort((a, b) => Math.abs(b.move_pct) - Math.abs(a.move_pct))
  .filter(c => !seen.has(c.variant_id) && seen.add(c.variant_id)).slice(0, s.digest_moves);
const RULE = { undercut: 'under the cheapest competitor', at_floor: 'at the floor', at_rrp: 'at RRP', cost_plus: 'cost plus', floor_fix: 'lifted to break-even' };
if (top.length) {
  blocks.push({ type: 'divider' }, { type: 'section', text: { type: 'mrkdwn', text: '*Biggest moves*' } });
  top.forEach((c, n) => blocks.push({ type: 'section', block_id: 'rev_' + n,
    text: { type: 'mrkdwn', text: `${c.title}\n${money(c.from_price)} → ${money(c.to_price)} (${pct(c.move_pct)}) · ${RULE[c.rule] || c.rule}` },
    ...(c.source === 'floor_fix' ? {} : { accessory: { type: 'button', action_id: 'price_revert', text: { type: 'plain_text', text: 'Revert' }, value: c.variant_id + '|' + c.run_id,
      confirm: { title: { type: 'plain_text', text: 'Put the old price back?' }, text: { type: 'mrkdwn', text: `Sets ${money(c.from_price)} and locks this variant.` },
        confirm: { type: 'plain_text', text: 'Revert' }, deny: { type: 'plain_text', text: 'Cancel' } } } }) }));
}
return [{ json: { text: `Prices: ${moves.length} changes in the last 24 hours`, blocks } }];
